// Glossary flashcards: chapter-4 terms (Tools and techniques), built from the study pages' vocabulary tables.
// Checked by tools/check_terms.js.
window.QTERMS = (window.QTERMS || []).concat([
  /* ---------- chapter 4 · Cell culture ---------- */
  { t: "in vitro", nl: "in vitro (in glas)", ch: 4, chs: [4], g: "Cell culture", d: "<b>In a test tube</b> with purified components, as opposed to <b>in vivo</b>: in a living cell or organism. Defines the minimal requirements of a process.", is: "way of doing an experiment", at: "the lab tube (in vitro) versus the living cell (in vivo)", org: "lab", pic: "cs4:c-culture" },
  { t: "purified components", nl: "gezuiverde componenten", ch: 4, chs: [4], g: "Cell culture", d: "Molecules <b>isolated from cells and cleaned</b>, used to rebuild a process (e.g. mRNA synthesis) in a tube.", is: "molecules (lab material)", at: "in the test tube", org: "lab" },
  { t: "high-throughput", nl: "hoge doorvoer", ch: 4, chs: [4], g: "Cell culture", d: "<b>Thousands of measurements at once</b>: sequencing, microarrays, robotics. Used on more than 10 000 tumours by The Cancer Genome Atlas.", is: "property of a method", at: "the lab, machines and computers", org: "lab", pic: "cs4:c-ngs" },
  { t: "conserved", nl: "geconserveerd", ch: 4, chs: [4], g: "Cell culture", d: "<b>Unchanged by evolution</b>, so the same in many species; why a model organism tells us about humans ('true for E. coli, true for the elephant').", is: "property of a gene or process", at: "genes and proteins across species", org: "all organisms" },
  { t: "model organism", nl: "modelorganisme", ch: 4, chs: [4], g: "Cell culture", d: "An <b>easy-to-grow species</b> (E. coli, yeast, worm, fly, Arabidopsis, mouse) used to study processes that apply to others: short generation time, small, storable, genetics possible, genome sequenced.", is: "organism (research tool)", at: "the lab", org: "bacteria, yeast, worm, fly, plant, mouse", pic: "cs4:c-culture" },
  { t: "generation time", nl: "generatietijd", ch: 4, chs: [4], g: "Cell culture", d: "Time from <b>one generation to the next</b>; short in good model organisms (minutes for E. coli).", is: "measure (time)", at: "a population of cells or organisms", org: "all organisms" },
  { t: "genetically tractable", nl: "genetisch hanteerbaar", ch: 4, chs: [4], g: "Cell culture", d: "Mutants can be <b>made, kept and studied</b> and modified genes introduced; a requirement for a model organism.", is: "property of an organism", at: "the lab", org: "model organisms" },
  { t: "nomenclature", nl: "naamgeving", ch: 4, chs: [4], g: "Cell culture", d: "The <b>naming system for genes and proteins</b>; it differs per organism (and genes are written in italics, proteins upright).", is: "convention", at: "in papers and databases", org: "all organisms" },
  { t: "cell culture", nl: "celkweek", ch: 4, chs: [4], g: "Cell culture", d: "Growing cells <b>outside the body</b>, in liquid medium or on a surface, under controlled conditions (air, temperature, nutrients).", is: "technique", at: "flasks, tubes and plates in the lab", org: "lab (bacteria, yeast, animal cells)", pic: "cs4:c-culture" },
  { t: "medium", nl: "medium (voedingsbodem)", ch: 4, chs: [4], g: "Cell culture", d: "The <b>nutrient mixture</b> cells grow in, buffered at the right pH; a pH indicator dye makes mammalian medium pink.", is: "lab material", at: "in the culture flask or tube", org: "lab" },
  { t: "agar", nl: "agar", ch: 4, chs: [4], g: "Cell culture", d: "A sugar polymer from algae: <b>liquid when hot, a gel when cool</b>. Added to medium it gives a solid plate on which single cells grow into colonies.", is: "lab material", at: "the solid medium in a Petri dish", org: "lab", pic: "cs4:c-culture" },
  { t: "colony", nl: "kolonie", ch: 4, chs: [4], g: "Cell culture", d: "A <b>visible dot of millions of identical cells</b>, grown from one cell on a plate: each colony is a clone.", is: "group of cells", at: "on the surface of an agar plate", org: "bacteria, yeast", pic: "p34:cloning#select" },
  { t: "primary cells", nl: "primaire cellen", ch: 4, chs: [4], g: "Cell culture", d: "Cells <b>freshly dissociated from a tissue</b>; they adhere to plastic, stop at confluence (contact inhibition) and divide a limited number of times.", is: "cell type (culture)", at: "attached to the bottom of a flask", org: "animal cells", pic: "cs4:c-culture" },
  { t: "contact inhibition", nl: "contactinhibitie", ch: 4, chs: [4], g: "Cell culture", d: "Cells that <b>touch each other stop dividing</b>, giving a single layer; transformed (cancer) cells ignore it and pile up.", is: "cell behaviour", at: "on the surface of a culture dish", org: "normal animal cells", pic: "cs4:c-culture" },
  { t: "telomerase", nl: "telomerase", ch: 4, chs: [4, 2], g: "Cell culture", d: "The enzyme that <b>rebuilds telomeres</b> (BIO01). Most primary cells lack it and senesce; tumour cell lines express it and divide forever.", is: "protein (enzyme with an RNA)", at: "at the chromosome ends in the nucleus", org: "humans (stem cells, cancer cells)", pic: "p12:hallmarks#replicative" },
  { t: "cell line", nl: "cellijn", ch: 4, chs: [4], g: "Cell culture", d: "Cells that <b>bypass senescence and divide indefinitely</b>, usually from a tumour (telomerase) or immortalised by a cancer-causing virus. Caveat: they differ from tissue cells and acquire mutations.", is: "cell population (culture)", at: "flasks in the lab, passed on for years", org: "lab (human, mouse cells)", pic: "cs4:c-culture" },

  /* ---------- chapter 4 · Stem cells and viruses ---------- */
  { t: "stem cell", nl: "stamcel", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A cell that <b>divides without limit</b> and can produce several cell types. Divides asymmetrically: one new stem cell, one cell that differentiates.", is: "cell type", at: "embryo (ES cells) or adult niches: skin, hair follicle, intestine, bone marrow", org: "humans (animals)", pic: "cs4:c-stem" },
  { t: "totipotent", nl: "totipotent", ch: 4, chs: [4], g: "Stem cells and viruses", d: "Can become <b>every cell type</b> of the body (syllabus wording for ES cells). Pluripotent = a restricted set of cell types (adult stem cells).", is: "property of a stem cell", at: "embryonic stem cells", org: "humans (animals)", trap: "Exam Q10: totipotent → any cell type; pluripotent → a subset.", pic: "cs4:c-stem" },
  { t: "pluripotent", nl: "pluripotent", ch: 4, chs: [4], g: "Stem cells and viruses", d: "(Syllabus) can become a <b>restricted set of cell types</b>; most adult stem cells. Elsewhere the word is often used for ES cells too.", is: "property of a stem cell", at: "adult stem cells (blood, skin, gut)", org: "humans (animals)", pic: "cs4:c-stem" },
  { t: "embryonic stem cell", nl: "embryonale stamcel (ES-cel)", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A stem cell <b>taken from an early embryo</b>; can be steered into neurons (> 99 % with growth factors) but undifferentiated leftovers can form a teratoma.", is: "cell type", at: "the early embryo (blastocyst); grown in culture", org: "humans, mouse", pic: "p34:knockout#es" },
  { t: "asymmetric division", nl: "asymmetrische deling", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A division whose two daughters have <b>different fates</b>: one stays a stem cell (self-renewal), the other differentiates.", is: "process", at: "a stem cell in its niche", org: "humans (animals)", pic: "cs4:c-stem" },
  { t: "hematopoietic stem cell", nl: "hematopoëtische stamcel (bloedstamcel)", ch: 4, chs: [4], g: "Stem cells and viruses", d: "The bone-marrow stem cell that produces <b>all blood cells</b> every day (hematopoiesis), via progenitor cells; the basis of bone marrow transplants.", is: "cell type", at: "the bone marrow (and some in blood)", org: "humans", pic: "cs4:c-stem" },
  { t: "progenitor cell", nl: "voorlopercel (progenitor)", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A <b>forerunner cell</b> between the stem cell and the final cell types; divides a few times, cannot self-renew forever.", is: "cell type", at: "bone marrow, developing tissues", org: "humans", pic: "cs4:c-stem" },
  { t: "teratoma", nl: "teratoom", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A tumour made of a <b>jumble of many differentiated cell types</b>; arises when ES cells are injected into a mouse or left undifferentiated in a transplant.", is: "tumour", at: "where undifferentiated ES cells were put", org: "mouse, humans", pic: "cs4:c-stem" },
  { t: "iPS cell", nl: "geïnduceerde pluripotente stamcel (iPS-cel)", ch: 4, chs: [4], g: "Stem cells and viruses", d: "<b>Induced pluripotent stem cell</b>: a differentiated skin cell reprogrammed to a stem cell by four transcription factors (brought in with a viral vector). Equivalent to ES cells; no embryo needed.", is: "cell type (made in the lab)", at: "from the patient's own skin cells, in culture", org: "humans, mouse", pic: "cs4:c-stem" },
  { t: "autologous transplant", nl: "autologe transplantatie", ch: 4, chs: [4], g: "Stem cells and viruses", d: "Transplant of cells <b>derived from the patient's own body</b> (e.g. from iPS cells); little rejection by the immune system.", is: "medical procedure", at: "the patient receiving their own cells back", org: "humans", pic: "cs4:c-stem" },
  { t: "viral vector", nl: "virale vector", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A <b>virus used as a vehicle</b> to deliver genes into cells, e.g. the four iPS transcription factors. Viruses must be grown in living cells.", is: "tool (modified virus)", at: "infects the target cells and brings the DNA in", org: "lab", pic: "p34:classes#dna" },
  { t: "detergent", nl: "detergent (zeepachtige stof)", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A <b>soap-like molecule that dissolves membranes</b>; used to break open cells to release virus particles, or (SDS) to unfold proteins.", is: "chemical", at: "added to cells or proteins in the tube", org: "lab" },
  { t: "assay", nl: "assay (meettest)", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A <b>test that measures how much</b> of something is present: a plaque assay counts live viruses, an activity assay measures an enzyme.", is: "kind of experiment", at: "the lab", org: "lab" },
  { t: "plaque", nl: "plaque", ch: 4, chs: [4], g: "Stem cells and viruses", d: "A <b>clear zone of dead cells</b> in a cell lawn on a plate, caused by one lytic virus particle spreading to neighbours. Number of plaques = number of live viruses.", is: "observation (spot on a plate)", at: "on a layer of cultured cells in a dish", org: "lab (lytic viruses)", pic: "cs4:c-stem" },

  /* ---------- chapter 4 · PCR and cDNA ---------- */
  { t: "PCR", nl: "PCR (polymerasekettingreactie)", ch: 4, chs: [4], g: "PCR and cDNA", d: "<b>Polymerase chain reaction</b>: repeated cycles of denaturing, primer binding and extension that double a chosen DNA stretch every cycle; 20 cycles give over a million copies.", is: "technique", at: "in a tube in a thermocycler", org: "lab", trap: "Exam Q13: you add nucleotides, primers and polymerase (to the template).", pic: "p34:pcr#double" },
  { t: "oligonucleotide", nl: "oligonucleotide", ch: 4, chs: [4], g: "PCR and cDNA", d: "A <b>short, chemically made chain of nucleotides</b> (about 20); used as a primer or a probe.", is: "DNA molecule (synthetic)", at: "made by a machine, added to the tube", org: "lab", pic: "p34:pcr#primers" },
  { t: "primer", nl: "primer", ch: 4, chs: [4], g: "PCR and cDNA", d: "A short single-stranded DNA that <b>binds a complementary site</b> and gives DNA polymerase a 3′ end to start from. Two primers set the boundaries of a PCR product.", is: "DNA molecule (oligonucleotide)", at: "paired to the 3′ end of each template strand", org: "lab (in cells: RNA primers, BIO01)", pic: "p34:pcr#primers" },
  { t: "denaturation", nl: "denaturatie", ch: 4, chs: [4], g: "PCR and cDNA", d: "<b>Separating the two DNA strands</b> by heat (94 to 98 °C) so primers can bind. (For proteins: unfolding by heat or SDS.)", is: "process (step 1 of PCR)", at: "the DNA in the tube", org: "lab", pic: "p34:pcr#denature" },
  { t: "annealing", nl: "annealing (aanhechting)", ch: 4, chs: [4], g: "PCR and cDNA", d: "A single strand <b>binding to its complementary partner</b> (= hybridisation): primers to the template at 50 to 65 °C; sticky ends to each other.", is: "process (step 2 of PCR)", at: "the single-stranded DNA in the tube", org: "lab", pic: "p34:pcr#anneal" },
  { t: "extension", nl: "extensie (verlenging)", ch: 4, chs: [4], g: "PCR and cDNA", d: "DNA polymerase <b>lengthens the primer along the template</b> at 72 °C, adding dNTPs 5′ → 3′ (step 3 of PCR).", is: "process (step 3 of PCR)", at: "from the primer's 3′ end along the template", org: "lab", pic: "p34:pcr#extend" },
  { t: "thermocycler", nl: "thermocycler (PCR-apparaat)", ch: 4, chs: [4], g: "PCR and cDNA", d: "The machine that <b>cycles the tube between the set temperatures</b> 20 to 40 times automatically.", is: "instrument", at: "the lab bench", org: "lab", pic: "cs4:c-pcr" },
  { t: "Taq polymerase", nl: "Taq-polymerase", ch: 4, chs: [4], g: "PCR and cDNA", d: "The <b>heat-stable DNA polymerase</b> of the hot-spring bacterium Thermus aquaticus; survives the 95 °C denaturation of every cycle.", is: "protein (enzyme)", at: "in the PCR tube, building the new strands", org: "lab (bacterial origin)", pic: "p34:pcr#taq" },
  { t: "dNTP", nl: "dNTP (nucleotide-bouwsteen)", ch: 4, chs: [4], g: "PCR and cDNA", d: "The four <b>DNA building blocks</b> (A, C, G, T with three phosphates and a 3′ OH) that a polymerase adds. A ddNTP lacks the 3′ OH and stops the chain.", is: "small molecule", at: "free in the tube, built into the new strand", org: "lab (and all cells)", pic: "p34:sanger#ddntp" },
  { t: "base pair", nl: "basenpaar (bp)", ch: 4, chs: [4], g: "PCR and cDNA", d: "Unit of DNA length: <b>one rung</b> of the ladder. kb = 1000 bp, Mbp = a million (E. coli genome 4.6 Mbp).", is: "unit", at: "counting along a DNA molecule", org: "all cells" },
  { t: "misincorporation", nl: "foute inbouw", ch: 4, chs: [4], g: "PCR and cDNA", d: "The polymerase <b>putting in a wrong base</b>; an early PCR error is copied into all later cycles. Fidelity = accuracy of copying (lowered on purpose for random mutagenesis).", is: "copying error", at: "in the new DNA strand", org: "lab", pic: "cs4:c-pcr" },
  { t: "cDNA", nl: "cDNA (complementair DNA)", ch: 4, chs: [4], g: "PCR and cDNA", d: "The <b>DNA copy of an mRNA</b>, made by reverse transcriptase; the RNA is degraded and a second strand added. Has <b>no introns</b>; can then be amplified by PCR.", is: "DNA molecule (made in the lab)", at: "in the tube, from mRNA; an RNA–DNA hybrid after the first strand", org: "lab", trap: "Exam Q11: reverse transcriptase makes cDNA from mRNA (correct pairing).", pic: "p34:cdna#rt" },

  /* ---------- chapter 4 · Cloning ---------- */
  { t: "DNA cloning", nl: "DNA-klonering", ch: 4, chs: [4], g: "Cloning", d: "<b>Isolating a DNA region and propagating it</b> (many identical copies) in cells, inside a vector. Recombinant DNA = DNA assembled from different sources.", is: "technique", at: "a plasmid in E. coli", org: "lab", pic: "p34:cloning#insert" },
  { t: "vector", nl: "vector (drager-DNA)", ch: 4, chs: [4], g: "Cloning", d: "A <b>carrier DNA</b> (plasmid or virus) that replicates in the host and holds the insert. Plasmids take inserts up to 15 kb, a BAC hundreds of kb.", is: "DNA molecule (tool)", at: "inside the host cell, separate from the chromosome", org: "lab (bacteria, yeast, cultured cells)", pic: "p34:cloning#vector" },
  { t: "insert", nl: "insert (ingebracht fragment)", ch: 4, chs: [4], g: "Cloning", d: "The <b>DNA fragment you put into the vector</b>, usually made by PCR with primers that carry restriction sites.", is: "DNA fragment", at: "ligated into the vector", org: "lab", pic: "p34:cloning#insert" },
  { t: "plasmid", nl: "plasmide", ch: 4, chs: [4], g: "Cloning", d: "A <b>circular double-stranded DNA</b> that replicates independently of the chromosome. pBR322: origin, ampicillin and tetracycline resistance, unique restriction sites.", is: "DNA molecule", at: "in the bacterial cytoplasm, next to the chromosome", org: "bacteria; lab", pic: "p34:plasmid#ori" },
  { t: "origin of replication", nl: "replicatie-oorsprong (ori)", ch: 4, chs: [4], g: "Cloning", d: "The sequence where the host machinery <b>starts copying the plasmid</b> (BIO01: origin), so the vector multiplies in E. coli.", is: "DNA sequence", at: "on the plasmid", org: "bacteria; lab", pic: "p34:plasmid#ori" },
  { t: "selectable marker", nl: "selecteerbare merker", ch: 4, chs: [4], g: "Cloning", d: "A gene (<b>antibiotic resistance</b>, or a metabolic enzyme) that lets <b>only cells with the vector grow</b> under chosen conditions; also the G418 resistance in knockout mice.", is: "gene (DNA)", at: "on the plasmid or targeting vector", org: "lab", pic: "p34:plasmid#amp" },
  { t: "restriction site", nl: "restrictieplaats", ch: 4, chs: [4], g: "Cloning", d: "The short <b>palindromic sequence</b> (4 to 8 bp) that a restriction enzyme recognises, e.g. GAATTC for EcoRI. A unique site occurs once in the vector.", is: "DNA sequence", at: "on the DNA to be cut (vector and insert)", org: "lab (bacterial origin)", pic: "p34:sticky#site" },
  { t: "BAC", nl: "BAC (bacterieel kunstmatig chromosoom)", ch: 4, chs: [4], g: "Cloning", d: "<b>Bacterial artificial chromosome</b>: a vector for inserts of hundreds of kilobases.", is: "DNA molecule (vector)", at: "in E. coli", org: "lab", pic: "p34:cloning#vector" },
  { t: "complementation", nl: "complementatie", ch: 4, chs: [4], g: "Cloning", d: "A cloned gene <b>restores the activity lost by a mutation</b>; used to find which gene is broken (transform a mutant with a library and look for rescue).", is: "experiment / idea", at: "a mutant cell receiving a good copy", org: "lab (yeast, bacteria)", pic: "proc:clone#library" },
  { t: "reporter gene", nl: "reportergen", ch: 4, chs: [4], g: "Cloning", d: "A gene whose product is <b>easy to see</b> (lacZ colour, luciferase light, GFP fluorescence, Spinach RNA), fused to a promoter or an ORF to show when and where a gene is active.", is: "gene (tool)", at: "on a plasmid or in the genome, next to the control region studied", org: "lab", pic: "cs4:c-rna" },
  { t: "tag", nl: "tag (label-stukje)", ch: 4, chs: [4], g: "Cloning", d: "A <b>short peptide or known piece</b> built into a protein (or nucleic acid) so it can be detected or caught for purification.", is: "part of a protein (added)", at: "fused to the protein of interest", org: "lab", pic: "cs4:c-protein" },
  { t: "restriction enzyme", nl: "restrictie-enzym", ch: 4, chs: [4], g: "Cloning", d: "A bacterial protein that <b>cuts double-stranded DNA at its restriction site</b>; a defence against foreign DNA, used in the lab to cut vector and insert.", is: "protein (enzyme)", at: "on the DNA at its recognition sequence", org: "bacteria; lab", trap: "Exam Q11: DNA ligase does not cut; restriction enzymes cut.", pic: "p34:sticky#cut" },
  { t: "palindrome", nl: "palindroom", ch: 4, chs: [4], g: "Cloning", d: "A DNA sequence that <b>reads the same 5′ → 3′ on both strands</b>, e.g. GAATTC / CTTAAG; restriction sites are palindromes, so the overhangs match.", is: "property of a DNA sequence", at: "the restriction site", org: "all DNA", pic: "p34:sticky#site" },
  { t: "sticky end", nl: "kleverig uiteinde (overhang)", ch: 4, chs: [4], g: "Cloning", d: "A short <b>single-stranded tail</b> (5′ or 3′ overhang) left by a restriction enzyme; it pairs with a matching tail. A blunt end is a straight cut.", is: "DNA end", at: "the ends of cut vector and insert", org: "lab", pic: "p34:sticky#overhang" },
  { t: "EcoRI", nl: "EcoRI", ch: 4, chs: [4], g: "Cloning", d: "Restriction enzyme from E. coli; site <b>GAATTC</b>, cuts after the G on both strands, leaving 5′ overhangs AATT.", is: "protein (enzyme)", at: "on GAATTC sites of the DNA", org: "bacteria; lab", pic: "p34:sticky#cut" },
  { t: "DNA ligase", nl: "DNA-ligase", ch: 4, chs: [4], g: "Cloning", d: "The enzyme that <b>joins DNA ends covalently</b> (seals the backbone) after the sticky ends have paired: ligation.", is: "protein (enzyme)", at: "at the nicks between insert and vector", org: "lab (and all cells, BIO01)", pic: "p34:cloning#ligate" },
  { t: "transformation", nl: "transformatie", ch: 4, chs: [4], g: "Cloning", d: "A bacterium <b>taking up DNA (a plasmid) from outside</b>. Cells are first made competent with salts or an electric field.", is: "process", at: "at the bacterial membrane, in the tube", org: "bacteria; lab", pic: "p34:cloning#transform" },
  { t: "competent cells", nl: "competente cellen", ch: 4, chs: [4], g: "Cloning", d: "Cells <b>made able to take up DNA</b>, by salt treatment or an electric field.", is: "cell state", at: "bacteria in the tube before transformation", org: "bacteria; lab", pic: "p34:cloning#transform" },
  { t: "selection", nl: "selectie", ch: 4, chs: [4], g: "Cloning", d: "Growing cells under conditions (<b>antibiotic plate</b>) in which only the wanted ones, those with the plasmid, survive.", is: "lab step", at: "on an agar plate with antibiotic", org: "lab", pic: "p34:cloning#select" },
  { t: "transgenic organism", nl: "transgeen organisme", ch: 4, chs: [4], g: "Cloning", d: "An organism carrying a <b>gene introduced from another organism</b> into its genome (transgenesis), e.g. a rat with rabbit insulin genes.", is: "kind of organism", at: "the added gene sits in the genome of every cell", org: "lab (animals, plants)", trap: "Exam Q14: a human treated with E. coli-made insulin is not transgenic.", pic: "cs4:c-library" },

  /* ---------- chapter 4 · Libraries and genetics ---------- */
  { t: "site-directed mutagenesis", nl: "plaatsgerichte mutagenese", ch: 4, chs: [4], g: "Libraries and genetics", d: "Putting a mutation at a <b>chosen place in a cloned gene</b>, to change or inactivate it (the syllabus gives no method).", is: "technique", at: "on a cloned gene in a plasmid", org: "lab", pic: "cs4:c-library" },
  { t: "library", nl: "bibliotheek (DNA-bibliotheek)", ch: 4, chs: [4], g: "Libraries and genetics", d: "A <b>collection of clones</b>, each with a different DNA fragment: genomic (whole genome, with introns) or cDNA (expressed genes of one tissue). Also: NGS library = adapter-tagged fragments.", is: "collection of DNA clones", at: "plasmids in many bacteria, or fragments in a tube", org: "lab", pic: "proc:clone#library" },
  { t: "genomic library", nl: "genomische bibliotheek", ch: 4, chs: [4], g: "Libraries and genetics", d: "Library of <b>fragments of the whole genome</b> (sheared or restriction-cut), each in its own plasmid; contains everything, including introns.", is: "collection of clones", at: "plasmids in bacteria", org: "lab", pic: "cs4:c-library" },
  { t: "cDNA library", nl: "cDNA-bibliotheek", ch: 4, chs: [4], g: "Libraries and genetics", d: "Library of <b>cDNA copies of the mRNAs</b> of one tissue or condition: only expressed genes, no introns.", is: "collection of clones", at: "plasmids in bacteria, made from a tissue's mRNA", org: "lab", pic: "cs4:c-library" },
  { t: "shearing", nl: "mechanisch breken (shearing)", ch: 4, chs: [4], g: "Libraries and genetics", d: "Breaking long DNA into pieces <b>by mechanical force</b>; the random fragmentation for a library or shotgun sequencing.", is: "lab step", at: "DNA in a tube", org: "lab", pic: "p34:shotgun#fragments" },
  { t: "expressed gene", nl: "tot expressie gebracht gen", ch: 4, chs: [4], g: "Libraries and genetics", d: "A gene that is <b>switched on</b>: transcribed into mRNA (and usually translated). cDNA libraries, microarrays and RNA-seq look only at these.", is: "state of a gene", at: "its mRNA present in the cell", org: "all cells", pic: "p34:microarray#hybridize" },
  { t: "forward genetics", nl: "voorwaartse genetica", ch: 4, chs: [4], g: "Libraries and genetics", d: "From a <b>mutant phenotype to the responsible gene</b>: make random mutants, screen for the property, then find the gene (e.g. by complementation).", is: "research strategy", at: "mutants in the lab", org: "lab", pic: "cs4:c-library" },
  { t: "reverse genetics", nl: "omgekeerde genetica", ch: 4, chs: [4], g: "Libraries and genetics", d: "From a <b>known gene to its function</b>: alter or delete the gene and look at the phenotype.", is: "research strategy", at: "a chosen gene in cells or an organism", org: "lab", pic: "cs4:c-library" },
  { t: "screen", nl: "screening", ch: 4, chs: [4], g: "Libraries and genetics", d: "<b>Looking through many mutants or clones</b> for the ones with a wanted property (e.g. radiation sensitivity).", is: "lab procedure", at: "plates or wells with many candidates", org: "lab" },
  { t: "knock-down", nl: "knock-down", ch: 4, chs: [4], g: "Libraries and genetics", d: "<b>Reducing the expression</b> of a gene (RNAi) without changing its DNA. A knockout inactivates the gene in the genome itself.", is: "experimental change", at: "the mRNA of the gene is destroyed in the cytoplasm", org: "lab", pic: "cs4:c-rnai" },
  { t: "homologous recombination", nl: "homologe recombinatie", ch: 4, chs: [4, 2], g: "Libraries and genetics", d: "<b>Exchange between DNA molecules with the same sequence</b>; used to replace or delete a chosen region (knockout mice) and as the precise repair route after a CRISPR cut.", is: "process", at: "on the DNA in the nucleus, between matching sequences", org: "all cells; lab", pic: "p34:crispr#hr" },

  /* ---------- chapter 4 · RNAi, CRISPR, knockout ---------- */
  { t: "RNA interference", nl: "RNA-interferentie (RNAi)", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "<b>Silencing a gene with a double-stranded RNA</b> that matches its mRNA: Dicer cuts it into siRNAs, Argonaute uses one strand to find and destroy the mRNA.", is: "process (natural and lab tool)", at: "in the cytoplasm, on the mRNA", org: "animals, plants, fungi; lab", pic: "cs4:c-rnai" },
  { t: "Dicer", nl: "Dicer", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "The enzyme that <b>cuts long dsRNA into siRNAs</b> of about 21 nucleotides.", is: "protein (enzyme)", at: "in the cytoplasm", org: "eukaryotes", pic: "cs4:c-rnai" },
  { t: "siRNA", nl: "siRNA (klein interfererend RNA)", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "<b>Small interfering RNA</b>: a double-stranded RNA piece of about 21 nucleotides; synthetic siRNAs are used to knock a gene down.", is: "RNA molecule", at: "in the cytoplasm, loaded into Argonaute", org: "eukaryotes; lab", pic: "cs4:c-rnai" },
  { t: "Argonaute", nl: "Argonaute", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "The protein that <b>holds one siRNA strand</b> and destroys the matching mRNA or blocks its translation.", is: "protein", at: "in the cytoplasm, on the target mRNA", org: "eukaryotes", pic: "cs4:c-rnai" },
  { t: "CRISPR", nl: "CRISPR", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "<b>Clustered regularly interspaced short palindromic repeats</b>: the bacterial DNA region that stores pieces of virus DNA (spacers) as an immune memory.", is: "DNA region (bacterial immune system)", at: "on the bacterial chromosome", org: "bacteria, archaea", pic: "p34:crispr#guide" },
  { t: "spacer", nl: "spacer", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "A <b>stored piece of virus DNA</b> in the CRISPR array (repeats and spacers in a row); transcribed into a crRNA that guides Cas.", is: "DNA sequence", at: "between the repeats of the CRISPR array", org: "bacteria", pic: "p34:crispr#guide" },
  { t: "crRNA", nl: "crRNA", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "The short RNA made from one spacer, which <b>guides Cas</b> to the matching virus DNA on the next attack.", is: "RNA molecule", at: "bound to the Cas nuclease", org: "bacteria", pic: "p34:crispr#guide" },
  { t: "Cas9", nl: "Cas9", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "A <b>CRISPR-associated nuclease</b> (DNA-cutting enzyme) that makes a double-strand break where its guide RNA pairs; the 'scissors' of genome editing.", is: "protein (enzyme)", at: "on the target DNA in the nucleus", org: "bacteria; lab (any organism)", pic: "p34:crispr#cas9" },
  { t: "guide RNA", nl: "gids-RNA (gRNA, sgRNA)", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "The <b>designed RNA that brings Cas9 to a chosen DNA sequence</b> by base pairing: the 'GPS' of the scissors.", is: "RNA molecule (designed)", at: "bound to Cas9, paired to the target DNA", org: "lab", pic: "p34:crispr#guide" },
  { t: "double-strand break", nl: "dubbelstrengsbreuk", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "<b>Both DNA strands cut at one place</b>; repaired by NHEJ (error-prone, gives deletions, knockout) or homologous recombination (precise, with a supplied template).", is: "DNA damage", at: "on the chromosome at the Cas9 target", org: "all cells", pic: "p34:crispr#cas9" },
  { t: "NHEJ", nl: "NHEJ (niet-homologe eindverbinding)", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "<b>Non-homologous end joining</b>: repair that glues broken DNA ends straight back together; error-prone, so it often deletes a few letters and knocks the gene out.", is: "repair process", at: "at a double-strand break in the nucleus", org: "all eukaryotes", pic: "p34:crispr#nhej" },
  { t: "CAR-T cells", nl: "CAR-T-cellen", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "A patient's <b>immune cells modified</b> (e.g. with CRISPR) to recognise and attack the tumour; a cancer-therapy application.", is: "cell type (engineered)", at: "T cells taken from the patient, changed, given back", org: "humans; lab", pic: "cs4:c-rnai" },
  { t: "germ line", nl: "kiembaan", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "The cells that <b>become eggs and sperm</b>; changes there are inherited by the next generation (the ethical issue of embryo editing; the goal of a knockout mouse).", is: "cell lineage", at: "the gonads (testes, ovaries)", org: "humans, mouse", pic: "p34:knockout#germline" },
  { t: "targeting vector", nl: "targeting-vector", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "DNA with <b>ends matching the gene and a marker in the middle</b>; by homologous recombination in ES cells it replaces the gene (G418 resistance selects the cells).", is: "DNA molecule (tool)", at: "brought into ES cells in culture", org: "lab (mouse)", pic: "p34:knockout#es" },
  { t: "blastocyst", nl: "blastocyst", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "A <b>very early embryo</b>: a hollow ball of a few hundred cells. Engineered ES cells are injected into it and join the tissues.", is: "stage of the embryo", at: "a few days after fertilisation, before implantation", org: "mouse (mammals)", pic: "p34:knockout#blastocyst" },
  { t: "chimera", nl: "chimeer (chimera)", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "An animal made of <b>cells of two different origins</b>; a knockout chimera has a patchy black-and-white coat. Backcrossing finds germline transmission; crossing heterozygotes gives homozygous knockouts.", is: "kind of organism", at: "the mouse born from the injected blastocyst", org: "mouse", pic: "p34:knockout#chimera" },
  { t: "surrogate mother", nl: "draagmoeder", ch: 4, chs: [4], g: "RNAi, CRISPR, knockout", d: "A <b>stand-in mother</b> (a black female mouse) that carries the injected blastocyst to birth.", is: "animal (role)", at: "the uterus of the female mouse", org: "mouse", pic: "p34:knockout#chimera" },

  /* ---------- chapter 4 · Detecting molecules ---------- */
  { t: "label", nl: "label (merker)", ch: 4, chs: [4], g: "Detecting molecules", d: "A <b>second molecule attached</b> to the molecule of interest to make it detectable: a radioactive atom, a fluorescent dye, an enzyme.", is: "molecule (tool)", at: "on the probe, antibody, nucleotide or cell studied", org: "lab" },
  { t: "absorbance", nl: "absorbantie (A)", ch: 4, chs: [4], g: "Detecting molecules", d: "A measure of how much <b>light a sample takes in</b>; plotted against wavelength it gives the absorption spectrum with the molecule's signature peaks.", is: "measurement", at: "a liquid sample in a cuvette in the spectrophotometer", org: "lab", pic: "p34:absorbance#dna" },
  { t: "wavelength", nl: "golflengte (nm)", ch: 4, chs: [4], g: "Detecting molecules", d: "The 'colour' of light, in <b>nanometres</b> (nm, a millionth of a millimetre); below 400 nm is ultraviolet (UV), 400 to 700 nm visible.", is: "property of light", at: "the light beam in the spectrophotometer", org: "lab" },
  { t: "A260 and A280", nl: "A260 en A280", ch: 4, chs: [4], g: "Detecting molecules", d: "DNA and RNA absorb most at <b>260 nm</b> (bases), proteins at <b>280 nm</b>. Ratio A260/A280 ≈ 2 for pure DNA, ≈ 0.6 for protein; DNA below 2 = protein contamination.", is: "measurement (purity check)", at: "a DNA or protein solution in the cuvette", org: "lab", pic: "p34:absorbance#ratio" },
  { t: "aromatic amino acids", nl: "aromatische aminozuren", ch: 4, chs: [4], g: "Detecting molecules", d: "<b>Tryptophan, tyrosine, phenylalanine</b>: ring-shaped side chains (BIO01) that absorb UV at 280 nm; they set a protein's extinction coefficient.", is: "amino acids (parts of proteins)", at: "in the protein chain", org: "all cells", pic: "p34:absorbance#protein" },
  { t: "chromophore", nl: "chromofoor", ch: 4, chs: [4], g: "Detecting molecules", d: "A group that <b>absorbs visible light</b> and gives a protein its colour: heme makes hemoglobin red; FAD (peaks at 380 and 450 nm) makes its enzymes yellow.", is: "chemical group (cofactor)", at: "bound inside a protein", org: "all cells", pic: "cs4:c-detect" },
  { t: "spectrophotometer", nl: "spectrofotometer", ch: 4, chs: [4], g: "Detecting molecules", d: "The instrument that <b>measures absorbance</b>: compares the light going in (I₀) and coming out (I) of a sample in a transparent cuvette.", is: "instrument", at: "the lab bench; the sample sits in the cuvette", org: "lab", pic: "cs4:c-detect" },
  { t: "Beer–Lambert law", nl: "wet van Beer-Lambert", ch: 4, chs: [4], g: "Detecting molecules", d: "<b>A = ε · l · c</b>: absorbance = extinction coefficient × path length (cm) × concentration (M). Known ε → the absorbance gives the concentration.", is: "formula", at: "applied to a cuvette measurement", org: "lab", pic: "cs4:c-detect" },
  { t: "extinction coefficient", nl: "extinctiecoëfficiënt (ε)", ch: 4, chs: [4], g: "Detecting molecules", d: "A <b>constant per molecule and wavelength</b> (ε, epsilon) telling how strongly it absorbs; for a protein at 280 nm set by its tryptophans and tyrosines.", is: "constant (number)", at: "a property of the molecule in solution", org: "lab", pic: "cs4:c-detect" },
  { t: "fluorochrome", nl: "fluorochroom (fluorescerende kleurstof)", ch: 4, chs: [4], g: "Detecting molecules", d: "A molecule that <b>glows</b>: absorbs light and re-emits it at a longer wavelength (fluorescence). Ethidium bromide, SYBR Green, DAPI, Cy3, Cy5, fluorescein, rhodamine, GFP.", is: "molecule (dye)", at: "bound to DNA, a probe, an antibody or a cell", org: "lab", pic: "cs4:c-detect" },
  { t: "ethidium bromide", nl: "ethidiumbromide", ch: 4, chs: [4], g: "Detecting molecules", d: "A DNA dye that <b>intercalates</b> (slips between the stacked base pairs) and fluoresces under UV; a mutagen. Safer: SYBR Green, SYBR Safe, GelRed.", is: "molecule (dye)", at: "between the base pairs of DNA in a gel", org: "lab", pic: "cs4:c-detect" },
  { t: "activity assay", nl: "activiteitsmeting", ch: 4, chs: [4], g: "Detecting molecules", d: "Measuring an enzyme by <b>what it produces</b> (a kinase by radioactive phosphate added), often via a coupled reaction with an easily measured product.", is: "kind of experiment", at: "an enzyme reaction in a tube", org: "lab", pic: "cs4:c-detect" },
  { t: "coupled reaction", nl: "gekoppelde reactie", ch: 4, chs: [4], g: "Detecting molecules", d: "<b>Linking the reaction of interest to a second reaction</b> whose product is easy to measure: topoisomerase II makes ADP, which drives NADH → NAD⁺, read at 340 nm.", is: "experimental trick", at: "several enzymes together in one tube", org: "lab", pic: "cs4:c-detect" },
  { t: "NADH", nl: "NADH / NAD⁺", ch: 4, chs: [4], g: "Detecting molecules", d: "A small <b>energy carrier</b>; NADH absorbs light at 340 nm, its oxidised form NAD⁺ does not, so a falling absorbance tracks a coupled reaction.", is: "small molecule (cofactor)", at: "free in the cell or the tube", org: "all cells; lab", pic: "cs4:c-detect" },

  /* ---------- chapter 4 · Gels and mass spectrometry ---------- */
  { t: "gel electrophoresis", nl: "gelelektroforese", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "<b>Pulling charged molecules through a porous gel</b> with an electric field; small ones move faster, so it sorts by size. DNA (negative) runs towards the positive pole.", is: "technique", at: "an agarose or polyacrylamide gel slab in buffer", org: "lab", trap: "Exam Q11: electrophoresis = separation of DNA fragments (correct pairing).", pic: "p34:gel#poles" },
  { t: "agarose", nl: "agarose", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "A gel material for <b>DNA and RNA</b>; polyacrylamide gives finer pores, for proteins (SDS-PAGE) and small DNA fragments (sequencing gels).", is: "material", at: "the gel slab", org: "lab", pic: "p34:gel#bands" },
  { t: "well", nl: "slot (well)", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "The <b>slot at the negative end</b> of the gel into which the sample is pipetted; each well gives one lane.", is: "part of a gel", at: "the top (negative) end of the gel", org: "lab", pic: "p34:gel#wells" },
  { t: "band", nl: "band (streep)", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "A <b>stripe in a lane</b>: all molecules of one size. A marker lane of known sizes is the ruler of the gel.", is: "observation on a gel", at: "in a lane of the gel, seen after staining", org: "lab", pic: "p34:gel#bands" },
  { t: "SDS", nl: "SDS (natriumdodecylsulfaat)", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "A <b>negatively charged detergent</b> that unfolds proteins and coats them with negative charge, so they run by molecular weight only; a reducing agent breaks the disulfide bonds.", is: "chemical", at: "bound all along the unfolded protein", org: "lab", pic: "cs4:c-gels" },
  { t: "SDS-PAGE", nl: "SDS-PAGE", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "<b>SDS-polyacrylamide gel electrophoresis</b>: proteins separated by molecular weight (stacking gel compacts, resolving gel separates); stained with Coomassie Brilliant Blue, marker in kDa.", is: "technique", at: "a polyacrylamide gel", org: "lab", pic: "cs4:c-gels" },
  { t: "kilodalton", nl: "kilodalton (kDa)", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "Unit of protein mass: <b>1000 daltons</b> (a dalton ≈ the mass of one hydrogen atom). Mass spectrometry weighs small molecules to within one dalton.", is: "unit", at: "the marker lane of a protein gel", org: "lab" },
  { t: "two-dimensional gel", nl: "tweedimensionale gel", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "Proteins separated by <b>charge in one direction, then by size</b> in the other; resolves hundreds of proteins as spots.", is: "technique", at: "a square polyacrylamide gel", org: "lab", pic: "cs4:c-gels" },
  { t: "mass spectrometry", nl: "massaspectrometrie (MS)", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "Identifying molecules by <b>weighing their ions</b>: make gas-phase ions (MALDI or ESI), separate by mass-to-charge ratio (m/z), detect. Identifies proteins from a gel spot.", is: "technique", at: "the mass spectrometer: ions flying in vacuum", org: "lab", pic: "cs4:c-gels" },
  { t: "m/z", nl: "m/z (massa gedeeld door lading)", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "<b>Mass divided by charge</b> of an ion; the x-axis of a mass spectrum.", is: "quantity", at: "each peak of the spectrum", org: "lab", pic: "cs4:c-gels" },
  { t: "MALDI", nl: "MALDI en ESI", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "Two ways to make gas-phase ions: <b>laser on a sample in a matrix</b> (MALDI) or a <b>spray in a strong electric field</b> (ESI, electrospray).", is: "ionisation methods", at: "the entrance of the mass spectrometer", org: "lab", pic: "cs4:c-gels" },
  { t: "trypsin", nl: "trypsine", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "A <b>protease that cuts proteins at predictable places</b> into peptides, whose masses are matched to the genome's predicted proteins.", is: "protein (enzyme)", at: "added to the protein sample before mass spectrometry", org: "lab (pancreas origin)", pic: "cs4:c-gels" },
  { t: "tandem MS", nl: "tandem-MS (MS/MS)", ch: 4, chs: [4], g: "Gels and mass spectrometry", d: "<b>Weigh a peptide, then break it up and weigh the pieces</b>: gives the amino acid sequence and modifications such as phosphorylation.", is: "technique", at: "inside the mass spectrometer", org: "lab", pic: "cs4:c-gels" },

  /* ---------- chapter 4 · Sequencing and BLAST ---------- */
  { t: "Sanger sequencing", nl: "Sanger-sequencing (ketenterminatie)", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "Chain-termination (dideoxy) sequencing: primer extension with dNTPs plus a few <b>ddNTPs that stop the chain</b>, giving fragments of every length, sorted by size and read; up to 900 bases.", is: "technique", at: "four reactions (or one with four colours) and a gel or capillary", org: "lab", pic: "p34:sanger#ladder" },
  { t: "ddNTP", nl: "ddNTP (dideoxynucleotide)", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "A building block <b>without a 3′ OH</b>: it can be added, but nothing can follow, so the chain ends there. Each of the four carries its own colour.", is: "small molecule (modified nucleotide)", at: "built in as the last base of a Sanger fragment", org: "lab", pic: "p34:sanger#ddntp" },
  { t: "autoradiography", nl: "autoradiografie", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "A photographic film <b>darkened by radioactive bands</b> in a gel; the old way to read Sanger ladders, four lanes read bottom to top.", is: "detection method", at: "a film laid on the gel", org: "lab", pic: "cs4:c-sanger" },
  { t: "capillary electrophoresis", nl: "capillaire elektroforese", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "Gel inside a <b>thin tube</b>; separates one sample by length, fragments pass a laser that reads the colour of the terminal ddNTP → chromatogram.", is: "technique", at: "a capillary in the automated sequencer", org: "lab", pic: "p34:sanger#chromatogram" },
  { t: "chromatogram", nl: "chromatogram", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "The row of <b>coloured peaks, one per base</b>, that the sequencer produces; read left to right it spells the sequence.", is: "output (graph)", at: "the sequencer's computer", org: "lab", pic: "p34:sanger#chromatogram" },
  { t: "alignment", nl: "alignering (uitlijning)", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "Two sequences written under each other so that <b>matching positions line up</b>; gaps may be inserted (with a penalty); the score measures similarity.", is: "comparison (computed)", at: "on the computer, query versus subject", org: "lab (bioinformatics)", pic: "cs4:c-sanger" },
  { t: "BLAST", nl: "BLAST", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "The NCBI search tool for <b>sequence alignments</b>: BLASTN for DNA (11-nucleotide seed), BLASTP for protein (3-amino-acid seed). Finds homologs and so hints at function.", is: "computer program", at: "the NCBI website, against a database", org: "lab (bioinformatics)", pic: "cs4:c-sanger" },
  { t: "E value", nl: "E-waarde", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "The <b>probability that an alignment is a chance match</b>; the lower, the better the homology.", is: "number (statistic)", at: "in the BLAST output per hit", org: "lab (bioinformatics)", pic: "cs4:c-sanger" },
  { t: "homolog", nl: "homoloog (gen)", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "Genes (or proteins) from <b>one ancestor</b> (BIO01); orthologs are the same gene in two species. Homology implies similar function, but check the active site.", is: "relation between genes", at: "genes in different genomes", org: "all organisms" },
  { t: "domain", nl: "domein (van een eiwit)", ch: 4, chs: [4, 2], g: "Sequencing and BLAST", d: "A <b>self-folding part of a protein with its own job</b> (kinase, zinc finger, DNA-binding); recognisable in alignments and a clue to function.", is: "part of a protein", at: "a stretch of the protein chain", org: "all cells", pic: "cs2:c-patterns" },
  { t: "transposase", nl: "transposase", ch: 4, chs: [4], g: "Sequencing and BLAST", d: "The enzyme that <b>moves a jumping piece of DNA</b>; Hermes (housefly) and Hobo (fruit fly) are the BLAST example of orthologs.", is: "protein (enzyme)", at: "on the DNA, at the transposon", org: "insects (eukaryotes)", pic: "cs4:c-sanger" },

  /* ---------- chapter 4 · Genome sequencing ---------- */
  { t: "shotgun sequencing", nl: "shotgun-sequencing", ch: 4, chs: [4], g: "Genome sequencing", d: "<b>Random fragmentation</b> of the genome, linkers on every fragment, PCR, read everything, then <b>reassemble by overlaps</b> on the computer.", is: "strategy", at: "fragments in a tube, reads on a computer", org: "lab", pic: "p34:shotgun#assembly" },
  { t: "adapter", nl: "adapter (linker)", ch: 4, chs: [4], g: "Genome sequencing", d: "<b>Short synthetic DNA ligated to both ends</b> of every fragment, so one primer fits all and fragments can stick to the Illumina surface.", is: "DNA molecule (synthetic)", at: "the ends of every library fragment", org: "lab", pic: "p34:illumina#adapters" },
  { t: "assembly", nl: "assemblage", ch: 4, chs: [4], g: "Genome sequencing", d: "<b>Chaining overlapping reads</b> by computer into contigs (contiguous pieces) and finally a genome; repetitive DNA is the hard part.", is: "computation", at: "on the computer", org: "lab (bioinformatics)", pic: "p34:shotgun#assembly" },
  { t: "over-sequencing", nl: "oversequencing", ch: 4, chs: [4], g: "Genome sequencing", d: "Reading <b>many times the genome length</b>: 8 genome equivalents give 99.9 % of bases (E. coli 4.6 Mbp → 37 Mbp), for errors, random coverage and overlaps.", is: "requirement (strategy)", at: "the total amount of sequence read", org: "lab", pic: "p34:shotgun#coverage" },
  { t: "depth of coverage", nl: "dekkingsdiepte (5X)", ch: 4, chs: [4], g: "Genome sequencing", d: "The <b>number of reads containing a given base</b>: 5X = in 5 reads. More depth = more confident variant calling; WGS > 30X, WES 50 to 100X, targeted > 500X.", is: "measure", at: "per base of the reference genome", org: "lab", pic: "p34:shotgun#coverage" },
  { t: "variant calling", nl: "variantbepaling", ch: 4, chs: [4], g: "Genome sequencing", d: "Deciding that a <b>difference from the reference is real</b>: a SNP (one letter), an indel (small insertion or deletion) or a structural variant.", is: "computation", at: "reads aligned to the reference genome", org: "lab (bioinformatics)", pic: "p34:shotgun#reads" },
  { t: "repetitive DNA", nl: "repetitief DNA", ch: 4, chs: [4], g: "Genome sequencing", d: "Sequences <b>present many times</b>; reads inside them cannot be placed, so short-read assemblies have gaps. Long reads (Nanopore) bridge them.", is: "kind of DNA", at: "scattered over the genome", org: "eukaryotes", pic: "p34:shotgun#assembly" },
  { t: "reference genome", nl: "referentiegenoom", ch: 4, chs: [4], g: "Genome sequencing", d: "A <b>finished genome used as a map</b> to align new reads (re-sequencing), instead of assembling from scratch.", is: "data (sequence)", at: "on the computer", org: "lab (bioinformatics)", pic: "p34:shotgun#reads" },
  { t: "next-generation sequencing", nl: "next-generation sequencing (NGS)", ch: 4, chs: [4], g: "Genome sequencing", d: "<b>Second-generation, massively parallel</b> methods reading millions of molecules together (Illumina). Third generation reads single molecules, no PCR, long reads (Nanopore).", is: "family of techniques", at: "a sequencer: extraction, library preparation, sequencing, data analysis", org: "lab", pic: "cs4:c-ngs" },
  { t: "reversible terminator", nl: "omkeerbare terminator", ch: 4, chs: [4], g: "Genome sequencing", d: "The Illumina nucleotide with a <b>removable 3′ block and a colour</b>: one base per cycle is added, imaged, then unblocked for the next cycle.", is: "small molecule (modified nucleotide)", at: "built into the growing strand on the Illumina surface", org: "lab", pic: "p34:illumina#cycle" },
  { t: "bridge amplification", nl: "brugamplificatie", ch: 4, chs: [4], g: "Genome sequencing", d: "On a lawn of primers, each fragment bends over into a <b>bridge and is copied</b> until a spot holds thousands of copies: a cluster bright enough to image.", is: "process (Illumina step)", at: "on the glass surface of the flow cell", org: "lab", pic: "p34:illumina#bridge" },
  { t: "sequencing by synthesis", nl: "sequencing-by-synthesis", ch: 4, chs: [4], g: "Genome sequencing", d: "<b>Reading each base at the moment it is built in</b> (Illumina): laser excites the dye, camera reads the colour of millions of clusters at once. Reads of 75 to 150 bp.", is: "principle", at: "clusters on the Illumina surface", org: "lab", pic: "p34:illumina#cluster" },
  { t: "nanopore", nl: "nanoporie", ch: 4, chs: [4], g: "Genome sequencing", d: "A <b>protein hole of a few nanometres</b> in a membrane; a motor protein feeds one DNA strand through, each base disturbs the current differently. Long reads, real time, portable (MinION), direct RNA.", is: "structure (sensor)", at: "a membrane in the flow cell between two chambers", org: "lab", pic: "p34:nanopore#pore" },
  { t: "ionic current", nl: "ionenstroom", ch: 4, chs: [4], g: "Genome sequencing", d: "<b>Flow of charged salt particles</b> through the pore under a voltage; the DNA base inside the pore partly blocks it, giving the signal.", is: "electrical signal", at: "through the nanopore", org: "lab", pic: "p34:nanopore#current" },
  { t: "structural variant", nl: "structurele variant", ch: 4, chs: [4], g: "Genome sequencing", d: "A <b>large change</b> (deletion, duplication, inversion, translocation) rather than one letter; best seen with long reads, aCGH or karyotyping.", is: "genetic difference", at: "a big stretch of a chromosome", org: "humans", pic: "p12:struct#translocation" },
  { t: "Walter Fiers", nl: "Walter Fiers (Gent)", ch: 4, chs: [4], g: "Genome sequencing", d: "Ghent scientist whose team sequenced the <b>first gene and the first complete genome</b> (bacteriophage MS2) in the 1970s with Sanger sequencing.", is: "person (history)", at: "Ghent University", org: "humans", pic: "cs4:c-shotgun" },

  /* ---------- chapter 4 · Sequencing applications ---------- */
  { t: "whole genome sequencing", nl: "volledige genoomsequencing (WGS)", ch: 4, chs: [4], g: "Sequencing applications", d: "Reading <b>all the DNA</b> of an organism, typically at > 30X; finds every kind of variant but needs big data, bioinformatics and raises privacy questions.", is: "technique (application)", at: "the whole genome, aligned to a reference", org: "lab", pic: "p34:wgswes#wgs" },
  { t: "whole exome sequencing", nl: "exoomsequencing (WES)", ch: 4, chs: [4], g: "Sequencing applications", d: "Sequencing only the <b>protein-coding exons</b> (1.5 % of the genome, ~21 000 genes) at 50 to 100X; cheaper, but misses promoters and splice sites.", is: "technique (application)", at: "the exons, captured with RNA probes", org: "lab", pic: "p34:wgswes#wes" },
  { t: "exome capture", nl: "exoomverrijking (capture)", ch: 4, chs: [4], g: "Sequencing applications", d: "<b>Fishing out exon fragments</b> with biotinylated RNA probes caught by streptavidin magnetic beads; the other 98.5 % is washed away, then the DNA is eluted.", is: "lab step", at: "in the tube: probes, beads, magnet", org: "lab", pic: "p34:wgswes#capture" },
  { t: "biotin and streptavidin", nl: "biotine en streptavidine", ch: 4, chs: [4], g: "Sequencing applications", d: "A vitamin and a protein that <b>stick to each other extremely tightly</b>: molecular Velcro. Biotinylated probes are pulled out with streptavidin beads.", is: "small molecule + protein (tools)", at: "biotin on the probe, streptavidin on the bead", org: "lab", pic: "p34:wgswes#capture" },
  { t: "targeted region sequencing", nl: "gerichte sequencing", ch: 4, chs: [4], g: "Sequencing applications", d: "Sequencing <b>only chosen regions</b> (known disease genes) at > 500X; the cheapest of the three approaches.", is: "technique (application)", at: "selected genomic regions", org: "lab", pic: "p34:wgswes#targeted" },
  { t: "metagenome sequencing", nl: "metagenoomsequencing", ch: 4, chs: [4], g: "Sequencing applications", d: "<b>All genomes of a sample sequenced together</b>, without culturing: which microbes live in the gut or an environment (the microbiome) and what they can do.", is: "technique (application)", at: "DNA from a mixed sample (gut, soil, water)", org: "lab (microbes)", pic: "cs4:c-wgs" },
  { t: "bisulfite sequencing", nl: "bisulfietsequencing", ch: 4, chs: [4], g: "Sequencing applications", d: "Maps <b>DNA methylation</b>: bisulfite converts only unmethylated C, so after sequencing methylated C's stand out (BIO01: methylation silences genes).", is: "technique (epigenomics)", at: "the C's of the genome", org: "lab", pic: "cs4:c-epirna" },
  { t: "ChIP-seq", nl: "ChIP-seq", ch: 4, chs: [4], g: "Sequencing applications", d: "<b>Chromatin immunoprecipitation + sequencing</b>: an antibody pulls out histones with a given mark, and the DNA around them is sequenced.", is: "technique (epigenomics)", at: "DNA bound to marked histones", org: "lab", pic: "cs4:c-epirna" },
  { t: "ATAC-seq", nl: "ATAC-seq", ch: 4, chs: [4], g: "Sequencing applications", d: "Sequencing of <b>transposase-accessible (open) chromatin</b>: maps where regulatory elements are active. DRIP-seq maps R-loops (RNA paired to DNA).", is: "technique (epigenomics)", at: "open regions of the chromatin", org: "lab", pic: "cs4:c-epirna" },
  { t: "transcriptome", nl: "transcriptoom", ch: 4, chs: [4], g: "Sequencing applications", d: "<b>All the RNA of a cell</b>; read by RNA-seq (deep sequencing of its cDNA), which gives expression levels, splice variants and noncoding RNAs.", is: "set of molecules", at: "all RNAs in the cytoplasm and nucleus", org: "all cells", pic: "cs4:c-epirna" },
  { t: "RNA-seq", nl: "RNA-seq", ch: 4, chs: [4], g: "Sequencing applications", d: "Isolate RNA, fragment, make cDNA, add adapters, <b>sequence millions of cDNAs</b>, map the reads: counts every RNA genome-wide. Caveat: reverse transcriptase can stall on structures.", is: "technique", at: "cDNA of the sample, reads mapped to the genome", org: "lab", pic: "proc:detect#rnaseq" },
  { t: "splice variant", nl: "splice-variant", ch: 4, chs: [4], g: "Sequencing applications", d: "A <b>different mRNA from the same gene</b> by using different exons (BIO01: splicing); seen by RNA-seq, missed by qRT-PCR.", is: "RNA molecule", at: "the mRNAs of one gene", org: "eukaryotes", pic: "cs4:c-epirna" },

  /* ---------- chapter 4 · Detecting DNA ---------- */
  { t: "restriction digestion pattern", nl: "restrictiepatroon", ch: 4, chs: [4], g: "Detecting DNA", d: "The <b>band pattern a DNA gives</b> after cutting with a restriction enzyme and running a gel; identifies or compares DNAs (idea only in the syllabus).", is: "technique (idea)", at: "bands on an agarose gel", org: "lab", pic: "cs4:c-cyto" },
  { t: "Southern blot", nl: "Southern blot", ch: 4, chs: [4], g: "Detecting DNA", d: "DNA bands <b>transferred from a gel to a membrane</b> and detected with a labelled probe that pairs with the sequence of interest (idea only in the syllabus).", is: "technique (idea)", at: "a membrane copy of a DNA gel", org: "lab", pic: "cs4:c-cyto" },
  { t: "probe", nl: "probe (sonde)", ch: 4, chs: [4], g: "Detecting DNA", d: "<b>Labelled single-stranded DNA</b> (or RNA) that pairs with its complementary sequence and marks the place: on a blot, on chromosomes (FISH) or for exome capture.", is: "DNA molecule (tool)", at: "hybridised to its target sequence", org: "lab", pic: "p34:fish#normal" },
  { t: "Giemsa stain", nl: "Giemsa-kleuring (bandering)", ch: 4, chs: [4], g: "Detecting DNA", d: "A dye giving <b>dark bands on gene-poor A/T-rich regions</b>; the banding pattern identifies each chromosome in a karyotype.", is: "dye (technique)", at: "on metaphase chromosomes spread on a slide", org: "lab", pic: "cs4:c-cyto" },
  { t: "metaphase spread", nl: "metafasespreiding", ch: 4, chs: [4], g: "Detecting DNA", d: "The <b>chromosomes of one dividing cell spread out</b> on a slide; cells are first cultured and arrested in metaphase (BIO01).", is: "preparation", at: "a microscope slide", org: "lab", pic: "cs4:c-cyto" },
  { t: "amniocentesis", nl: "vruchtwaterpunctie", ch: 4, chs: [4], g: "Detecting DNA", d: "<b>Prenatal screening</b>: fluid with fetal cells is taken from the sac around the fetus; the cells are cultured and karyotyped for aneuploidy.", is: "medical procedure", at: "the amniotic fluid of a pregnant woman", org: "humans", pic: "cs4:c-cyto" },
  { t: "FISH", nl: "FISH (fluorescentie-in-situhybridisatie)", ch: 4, chs: [4], g: "Detecting DNA", d: "<b>Fluorescence in situ hybridisation</b>: a fluorescent probe on chromosomes fixed on a slide shows where a sequence sits; DAPI stains all DNA blue. Needs prior knowledge of the region.", is: "technique", at: "cells fixed and permeabilised on a glass slide", org: "lab", pic: "p34:fish#normal" },
  { t: "merged signal", nl: "samengevoegd signaal (geel)", ch: 4, chs: [4], g: "Detecting DNA", d: "Two FISH probe colours <b>overlapping (green + red = yellow)</b> because a translocation brought two regions together (leukemia 4;11 example).", is: "observation", at: "on the rearranged chromosome under the microscope", org: "lab", pic: "p34:fish#translocation" },
  { t: "array CGH", nl: "array-CGH", ch: 4, chs: [4], g: "Detecting DNA", d: "<b>Array comparative genomic hybridisation</b>: patient DNA (green) and reference DNA (red) co-hybridised to a genome-wide chip; yellow = equal, red = deletion, green = duplication. Quantitative, no prior knowledge needed.", is: "technique", at: "a microarray of genomic fragments", org: "lab", pic: "p34:acgh#array" },
  { t: "fluorescein and rhodamine", nl: "fluoresceïne en rhodamine", ch: 4, chs: [4], g: "Detecting DNA", d: "A <b>green-emitting and a red-emitting</b> fluorescent dye, used to label the two DNA pools in aCGH.", is: "molecules (dyes)", at: "attached to the labelled DNA", org: "lab", pic: "p34:acgh#label" },

  /* ---------- chapter 4 · Detecting RNA, proteins, cells ---------- */
  { t: "qRT-PCR", nl: "qRT-PCR (kwantitatieve RT-PCR)", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "<b>Quantitative reverse transcription PCR</b>: RNA → cDNA → PCR, product measured after every cycle (real time) to find how much of one RNA there was. Very sensitive; sees only the primer stretch.", is: "technique", at: "a real-time thermocycler", org: "lab", pic: "p34:qpcr#curves" },
  { t: "exponential phase", nl: "exponentiële fase", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "The PCR cycles in which the <b>product still doubles each time</b>; only here is the amount proportional to the input RNA.", is: "phase of the reaction", at: "the early, steep part of the amplification curve", org: "lab", pic: "p34:qpcr#curves" },
  { t: "threshold cycle", nl: "drempelcyclus", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "The cycle at which a sample's fluorescence <b>crosses a fixed level</b>: more RNA = fewer cycles (about 18 for 100 ng, 25 for 1 ng, 35 for 1 pg).", is: "measurement", at: "read from the amplification curves", org: "lab", pic: "p34:qpcr#threshold" },
  { t: "nanogram", nl: "nanogram en picogram (ng, pg)", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "<b>ng = a billionth of a gram</b> (10⁻⁹), pg = a trillionth (10⁻¹²); 1 pg is a thousand times less than 1 ng.", is: "units", at: "amounts of RNA or DNA in a sample", org: "lab" },
  { t: "luciferase", nl: "luciferase", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "A <b>firefly enzyme that produces light</b>; a reporter protein, like β-galactosidase (lacZ, blue colour) and GFP.", is: "protein (enzyme, reporter)", at: "made in the cells carrying the reporter gene", org: "lab (firefly origin)", pic: "cs4:c-rna" },
  { t: "DNA microarray", nl: "DNA-microarray (chip)", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "A slide with <b>thousands of DNA spots, one per gene</b>; labelled cDNA of two samples (Cy3 green, Cy5 red) hybridises; yellow = equal, red or green = up or down. Expression genome-wide.", is: "technique (tool)", at: "a glass chip; spots scanned by a laser", org: "lab", trap: "Exam Q15: which genes two cell types express → a DNA microarray.", pic: "p34:microarray#colours" },
  { t: "Cy3 and Cy5", nl: "Cy3 en Cy5", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "<b>Green and red fluorescent dyes</b> used to label the cDNA of two samples for a microarray.", is: "molecules (dyes)", at: "attached to the cDNA", org: "lab", pic: "p34:microarray#cdna" },
  { t: "clustering", nl: "clustering", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "Placing genes with <b>similar expression patterns next to each other</b> in the display (yeast cell-cycle example).", is: "computation (display)", at: "the microarray data on the computer", org: "lab (bioinformatics)", pic: "cs4:c-rna" },
  { t: "antibody", nl: "antistof (antilichaam)", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "A <b>Y-shaped immune protein</b> that binds one target with high affinity and specificity; made by immunising an animal with the protein or a peptide.", is: "protein", at: "made by immune cells; in the lab, in solution on a blot or on cells", org: "humans (animals); lab", pic: "p34:western#antibodies" },
  { t: "primary and secondary antibody", nl: "primaire en secundaire antistof", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "The antibody <b>against your protein</b>; and an antibody against the primary that <b>carries the label</b> (radioactivity, fluorophore or an enzyme such as horseradish peroxidase).", is: "proteins (tools)", at: "bound to the protein on the membrane", org: "lab", pic: "p34:western#secondary" },
  { t: "Western blot", nl: "Western blot (immunoblot)", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "Proteins from an SDS-PAGE gel <b>transferred to a membrane</b> (electric field), blocked with BSA, and <b>detected with antibodies</b>: one protein's presence and size.", is: "technique", at: "a membrane copy of the protein gel", org: "lab", pic: "p34:western#transfer" },
  { t: "blocking", nl: "blokkeren (met BSA)", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "Covering the empty membrane with a <b>cheap protein</b> (bovine serum albumin) so antibodies bind only their target, not the membrane.", is: "lab step", at: "the membrane before the antibodies", org: "lab", pic: "p34:western#block" },
  { t: "Ponceau S", nl: "Ponceau S", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "A <b>red dye that shows all proteins</b> on the membrane after transfer, including the marker lane.", is: "dye", at: "on the membrane", org: "lab", pic: "p34:western#transfer" },
  { t: "cross-reactivity", nl: "kruisreactiviteit", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "An antibody <b>also binding other proteins</b> than its target; polyclonal antibodies (a mixture recognising several spots, epitopes) are prone to it, so include controls.", is: "problem (property of antibodies)", at: "on the blot: extra bands", org: "lab", pic: "p34:western#detect" },
  { t: "flow cytometry", nl: "flowcytometrie", ch: 4, chs: [4], g: "Detecting RNA, proteins, cells", d: "Cells in <b>single file pass a laser</b>; scattered light gives size and shape, fluorescent tags give markers. Thousands of cells per minute: leukemia diagnosis, immune monitoring in HIV.", is: "technique", at: "a stream of cells through the cytometer", org: "lab", pic: "p34:flow#laser" }
]);
